import { useState, FormEvent } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  const showError = email.length > 0 && !isEmailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isEmailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '420px' }}>
      {submitted ? (
        <JxAlert intent="success" title="Приглашение отправлено">
          {email} получит приглашение в команду.
        </JxAlert>
      ) : null}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          helperText="На эту почту придёт ссылка для входа в команду"
          value={email}
          onChange={(event) => {
            setEmail(event.target.value);
            setSubmitted(false);
          }}
          errorText={showError ? 'Похоже, это не email-адрес' : undefined}
        />

        <JxSelect
          label="Роль"
          options={[
            { value: 'admin', label: 'Администратор' },
            { value: 'member', label: 'Участник' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!isEmailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

